        <div className="mt-48 pt-32 border-t border-black/5 relative pb-32">
          <div className="flex flex-col lg:flex-row gap-24 relative">

            {/* Sidebar Navigation */}
            <aside className="lg:w-[30%] lg:sticky lg:top-[180px] lg:h-fit">
